# D44 · Part 0~5 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d44_flow.py   (모의 부품만 써요 · 인터넷·GPU·Docker·마이크 불필요)
#   깨움말 학습(합성 소리) → 흘러 들어오는 소리에서 감지 → 상태 기계(듣기·생각·말하기) → 기기 예산 판정 → 클라우드/기기 선택을 인터넷·GPU 없이 한 파일로
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import numpy as np

SR = 16000                                     # 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
FRAME = 1280                                   # 0.08초 조각 = 스트리밍의 한 걸음
WIN = 5                                        # 0.4초 = 조각 5개를 이어서 본다
CENTERS = np.arange(8) * 500 + 250             # 얼어 있는 앞단: 주파수 띠 8개의 가운데 (250, 750, ... 3750 Hz)
_E = np.exp(-2j * np.pi * CENTERS[:, None] * np.arange(FRAME) / SR)
A, B, C = 750, 1750, 2750                      # 낮은 소리 · 높은 소리 · 더 높은 소리
WAKE = [A, A, B, B, B]                         # "하나야" 흉내(합성 신호): 낮은 소리 2조각 → 높은 소리 3조각
DECOYS = [[B, B, A, A, A], [A] * 5, [C] * 5, [A, B, A, B, A], [B] * 5, [C, C, A, A, A]]   # 비슷하지만 다른 소리


def frame_feats(y):
    """앞단(학습하지 않음): 0.08초 조각마다 8개 띠의 로그 에너지 → (조각 수, 8)"""
    f = y[: len(y) // FRAME * FRAME].reshape(-1, FRAME)
    return np.log(np.abs(f @ _E.T) ** 2 / FRAME ** 2 + 1e-9)


def tones(freqs, rng, jitter=30.0, amp=0.3):
    t = np.arange(FRAME) / SR
    return np.concatenate([amp * rng.uniform(0.8, 1.2) * np.sin(2 * np.pi * (f + rng.uniform(-jitter, jitter)) * t + rng.uniform(0, 6.28)) for f in freqs])


def noise(n, rng, amp=0.02):
    return rng.uniform(-1, 1, n) * amp


def window_sample(freqs, rng, shift=0):
    """소리 5조각(앞뒤 잡음 포함)에서 shift 조각 어긋난 0.4초 창을 잘라 특징 40개로"""
    y = np.concatenate([noise(2 * FRAME, rng), tones(freqs, rng), noise(2 * FRAME, rng)]) + noise(9 * FRAME, rng)
    return frame_feats(y[(2 + shift) * FRAME:(2 + shift + WIN) * FRAME]).reshape(-1)


def make_data(n, seed):
    """깨움말 창 (정확히 맞은 것 + 한 조각 어긋난 것)을 정답(1), 비슷한 소리 · 잡음 창을 오답(0)으로"""
    rng = np.random.default_rng(seed)
    X, y = [], []
    for i in range(n):
        X.append(window_sample(WAKE, rng, shift=(0, -1, 1)[i % 3])); y.append(1)
        X.append(window_sample(DECOYS[i % len(DECOYS)], rng, shift=(0, -1, 1)[(i // 2) % 3])); y.append(0)
        X.append(frame_feats(noise(WIN * FRAME, rng)).reshape(-1)); y.append(0)
    return np.array(X), np.array(y)


def train(X, y, epochs=400, lr=0.5):
    """작은 분류기: 표준화 + 로지스틱 회귀 (장난감 모델, 학습은 순식간)"""
    mu, sd = X.mean(0), X.std(0) + 1e-6
    Z = (X - mu) / sd
    w, b = np.zeros(Z.shape[1]), 0.0
    for _ in range(epochs):
        g = 1 / (1 + np.exp(-(Z @ w + b))) - y
        w -= lr * Z.T @ g / len(y)
        b -= lr * g.mean()
    return dict(mu=mu, sd=sd, w=w, b=b)


def score(model, x):
    return 1 / (1 + np.exp(-(((x - model["mu"]) / model["sd"]) @ model["w"] + model["b"])))


def stream_scores(model, y):
    """흘러 들어온 소리를 0.08초 조각씩 받아, 조각마다 최근 0.4초 창의 점수 하나 (처음 4조각은 아직 창이 안 차서 0)"""
    feats = frame_feats(y)
    return [0.0] * (WIN - 1) + [float(score(model, feats[i - WIN + 1:i + 1].reshape(-1))) for i in range(WIN - 1, len(feats))]


def detect(scores, thr, need=2, rest=19):
    """점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각(약 1.5초)은 쉬는 시간 → 깨어난 조각 번호들"""
    fires, run, cool = [], 0, 0
    for i, s in enumerate(scores):
        if cool > 0:
            cool -= 1
            continue
        run = run + 1 if s > thr else 0
        if run >= need:
            fires.append(i)
            run, cool = 0, rest
    return fires


def make_stream(rng, wake_at=(37, 100), decoy_at=(70,), n=150):
    """12초 소리: 잡음 위에 깨움말 2번(약 3.0초 · 8.0초)과 비슷한 소리 1번(5.6초)"""
    y = noise(n * FRAME, rng)
    for at in wake_at:
        y[at * FRAME:(at + WIN) * FRAME] += tones(WAKE, rng)
    for at in decoy_at:
        y[at * FRAME:(at + WIN) * FRAME] += tones(DECOYS[0], rng)
    return y

def voiced_frames(y, thr=0.05):
    """조각마다 소리 크기(RMS)가 문턱을 넘으면 '말하는 중'"""
    f = y[: len(y) // FRAME * FRAME].reshape(-1, FRAME)
    return [bool(v) for v in (np.sqrt((f ** 2).mean(1)) > thr)]


def run_machine(fires, voiced, quiet_need=5, give_up=25, think=3, speak=20):
    """비서의 상태: 대기 → (깨움말) 듣기 → (말이 끝남) 생각 → 말하기 → 대기. 말하는 중에 깨움말이 다시 오면 끊고 듣기로(barge-in)"""
    state, log = "wait", [(0, "wait")]
    heard = quiet = left = t0 = 0
    for i, v in enumerate(voiced):
        fired, before = i in fires, state
        if state == "wait":
            if fired:
                state, heard, quiet, t0 = "listen", 0, 0, i
        elif state == "listen":
            if v:
                heard, quiet = heard + 1, 0
            elif heard:
                quiet += 1
            if heard and quiet >= quiet_need:
                state, left = "think", think
            elif not heard and i - t0 > give_up:                 # 아무 말도 없으면 포기하고 대기로
                state = "wait"
        elif state == "think":
            left -= 1
            if left == 0:
                state, left = "speak", speak
        elif state == "speak":
            if fired:
                state, heard, quiet, t0 = "listen", 0, 0, i
            else:
                left -= 1
                if left == 0:
                    state = "wait"
        if state != before:
            log.append((i, state))
    return log

def make_talk(rng):
    """깨움말(10~14조각) → 손님 말(20~34조각) → 비서가 말하는 중 깨움말 다시(52~56조각)"""
    y = noise(110 * FRAME, rng)
    for at, freqs in [(10, WAKE), (20, [C] * 5), (25, [C] * 5), (30, [C] * 5), (52, WAKE)]:
        y[at * FRAME:(at + WIN) * FRAME] += tones(freqs, rng)
    return y

import time

BUDGET = dict(size_mb=300, ram_mb=512, load_s=5.0, rtf=0.5)       # 기기(저가 단말, 가상)의 예산. rtf = 처리 시간 ÷ 소리 길이 (1 이하여야 실시간)
PARTS = {                                                         # 부품별 잰 값 (예시 숫자: 진짜 모델을 내려받아 재는 대신 표로 둠)
    "깨움말": dict(size_mb=0.02, ram_mb=5, load_s=0.1, rtf=0.02),
    "ASR small fp32": dict(size_mb=970, ram_mb=1800, load_s=9.0, rtf=1.4),
    "ASR base int8": dict(size_mb=78, ram_mb=300, load_s=1.5, rtf=0.25),
    "TTS": dict(size_mb=60, ram_mb=200, load_s=1.0, rtf=0.15),
}


def over_budget(measured, budget):
    """예산을 넘은 항목 이름들 (같은 키끼리 비교)"""
    return sorted(k for k, v in measured.items() if v > budget[k])


def total(names):
    """고른 부품을 한 기기에 함께 올릴 때: 크기 · 메모리 · 올리는 시간 · rtf 는 모두 더함(차례로 돌리므로)"""
    return {k: sum(PARTS[n][k] for n in names) for k in BUDGET}


def measure_toy():
    """진짜로 재 보기: 12초 합성 소리에서 조각마다 띠 에너지를 뽑는 데 걸린 시간 ÷ 12초 (rtf)"""
    y = np.random.default_rng(0).uniform(-1, 1, 12 * SR).astype(np.float32) * 0.1
    t0 = time.perf_counter()
    f = y[: len(y) // FRAME * FRAME].reshape(-1, FRAME)
    np.log(np.abs(np.fft.rfft(f, axis=1)) ** 2 + 1e-9)
    return (time.perf_counter() - t0) / 12

def choose(offline, privacy_high, needs_big_llm, latency_ms):
    """클라우드 · 기기 · 섞기 중 고르기: 위에서부터 먼저 맞는 규칙이 이긴다 → (고른 것, 이유)"""
    if offline:
        return "device", "인터넷이 없어도 돌아야 함"
    if needs_big_llm and privacy_high:
        return "hybrid", "깨움말 · 받아쓰기는 기기, 생각은 클라우드(개인정보는 가려서)"
    if needs_big_llm:
        return "cloud", "큰 LLM이 필요함"
    if privacy_high:
        return "device", "소리가 기기 밖으로 나가면 안 됨"
    if latency_ms < 300:
        return "device", "네트워크 왕복 시간을 쓸 수 없음"
    return "cloud", "특별한 제약이 없으면 관리가 쉬운 클라우드"


def break_even_calls(device_won, cloud_won_per_call):
    """기기를 한 대 사는 돈(원)이 클라우드 통화 요금(원)과 같아지는 통화 수 (올림, 정수)"""
    return -(-device_won // cloud_won_per_call)

model = train(*make_data(120, seed=0))                                   # 1) 작은 깨움말 분류기 (진짜 TTS · sherpa-onnx 대신 합성 소리)
y = make_talk(np.random.default_rng(7))
fires = detect(stream_scores(model, y), 0.9)                              # 2) 0.08초 조각마다 점수 → 연속 확인 + 쉬는 시간
log = run_machine(set(fires), voiced_frames(y))                           # 3) 비서의 상태
print("깨움말 감지:", fires, "| 상태:", " → ".join(s for _, s in log))

for name, names in [("A (small fp32)", ["깨움말", "ASR small fp32", "TTS"]), ("B (base int8)", ["깨움말", "ASR base int8", "TTS"])]:
    print(f"예산 {name}: 넘은 항목 {over_budget(total(names), BUDGET) or '없음'}")                  # 4) 기기 예산
over_a, over_b = over_budget(total(["깨움말", "ASR small fp32", "TTS"]), BUDGET), over_budget(total(["깨움말", "ASR base int8", "TTS"]), BUDGET)
toy = measure_toy()
print(f"장난감 앞단의 rtf {toy:.4f} (예산 {BUDGET['rtf']} 이하여야 실시간)")
c1, c2 = choose(False, True, True, 500), choose(True, False, True, 1000)   # 5) 클라우드 · 기기 선택
print("선택:", c1, c2, "| 손익분기 통화 수", break_even_calls(30000, 8))
check(fires == [14, 56] and [s for _, s in log] == ["wait", "listen", "think", "speak", "listen", "wait"] and over_a == ["load_s", "ram_mb", "rtf", "size_mb"] and over_b == []
      and toy < BUDGET["rtf"] and c1[0] == "hybrid" and c2[0] == "device" and break_even_calls(30000, 8) == 3750,
      "깨움말 2번 감지, 상태 순서, fp32 조합은 예산 초과 · int8 조합은 통과, 개인정보+큰 LLM은 hybrid, 오프라인은 device 여야 해요.")

flow.typescript:
// D44 · Part 0~5 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_flow.ts
//   깨움말 학습(합성 소리) → 흘러 들어오는 소리에서 감지 → 상태 기계(듣기·생각·말하기) → 기기 예산 판정 → 클라우드/기기 선택을 인터넷·GPU 없이 한 파일로
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const FRAME = 1280; // 0.08초 조각 = 스트리밍의 한 걸음
const WIN = 5; // 0.4초 = 조각 5개를 이어서 본다
const CENTERS = Array.from({ length: 8 }, (_, i) => i * 500 + 250); // 얼어 있는 앞단: 주파수 띠 8개의 가운데 (250, 750, ... 3750 Hz)
const [A, B, C] = [750, 1750, 2750]; // 낮은 소리 · 높은 소리 · 더 높은 소리
const WAKE = [A, A, B, B, B]; // "하나야" 흉내(합성 신호): 낮은 소리 2조각 → 높은 소리 3조각
const DECOYS = [[B, B, A, A, A], [A, A, A, A, A], [C, C, C, C, C], [A, B, A, B, A], [B, B, B, B, B], [C, C, A, A, A]]; // 비슷하지만 다른 소리

let seed = 2024;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }; // 0~1 (재현 가능한 난수)
const uni = (lo: number, hi: number): number => lo + (hi - lo) * rand();

function frameFeats(y: Float32Array): number[][] {
  // 앞단(학습하지 않음): 0.08초 조각마다 8개 띠의 로그 에너지 → (조각 수, 8)
  const out: number[][] = [];
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    out.push(CENTERS.map((fc) => {
      let re = 0, im = 0;
      for (let n = 0; n < FRAME; n++) { const ph = (2 * Math.PI * fc * n) / SR; re += y[s + n] * Math.cos(ph); im -= y[s + n] * Math.sin(ph); }
      return Math.log((re * re + im * im) / (FRAME * FRAME) + 1e-9);
    }));
  }
  return out;
}

function tones(freqs: number[], jitter = 30, amp = 0.3): Float32Array {
  const y = new Float32Array(freqs.length * FRAME);
  freqs.forEach((f0, k) => {
    const f = f0 + uni(-jitter, jitter), a = amp * uni(0.8, 1.2), ph = uni(0, 6.28);
    for (let n = 0; n < FRAME; n++) y[k * FRAME + n] = a * Math.sin(2 * Math.PI * f * (n / SR) + ph);
  });
  return y;
}
const noise = (n: number, amp = 0.02): Float32Array => Float32Array.from({ length: n }, () => uni(-1, 1) * amp);

function windowSample(freqs: number[], shift = 0): number[] {
  // 소리 5조각(앞뒤 잡음 포함)에서 shift 조각 어긋난 0.4초 창을 잘라 특징 40개로
  const y = noise(9 * FRAME);
  y.set(tones(freqs).map((v, i) => v + y[2 * FRAME + i]), 2 * FRAME);
  return frameFeats(y.slice((2 + shift) * FRAME, (2 + shift + WIN) * FRAME)).flat();
}

function makeData(n: number): [number[][], number[]] {
  // 깨움말 창 (정확히 맞은 것 + 한 조각 어긋난 것)을 정답(1), 비슷한 소리 · 잡음 창을 오답(0)으로
  const X: number[][] = [], y: number[] = [];
  const shifts = [0, -1, 1];
  for (let i = 0; i < n; i++) {
    X.push(windowSample(WAKE, shifts[i % 3])); y.push(1);
    X.push(windowSample(DECOYS[i % DECOYS.length], shifts[Math.floor(i / 2) % 3])); y.push(0);
    X.push(frameFeats(noise(WIN * FRAME)).flat()); y.push(0);
  }
  return [X, y];
}

interface Model { mu: number[]; sd: number[]; w: number[]; b: number }
function train(X: number[][], y: number[], epochs = 400, lr = 0.5): Model {
  // 작은 분류기: 표준화 + 로지스틱 회귀 (장난감 모델, 학습은 순식간)
  const d = X[0].length, n = X.length;
  const mu = Array.from({ length: d }, (_, j) => X.reduce((a, r) => a + r[j], 0) / n);
  const sd = Array.from({ length: d }, (_, j) => Math.sqrt(X.reduce((a, r) => a + (r[j] - mu[j]) ** 2, 0) / n) + 1e-6);
  const Z = X.map((r) => r.map((v, j) => (v - mu[j]) / sd[j]));
  const w = new Array(d).fill(0);
  let b = 0;
  for (let e = 0; e < epochs; e++) {
    const gw = new Array(d).fill(0);
    let gb = 0;
    for (let i = 0; i < n; i++) {
      const g = 1 / (1 + Math.exp(-(Z[i].reduce((a, v, j) => a + v * w[j], 0) + b))) - y[i];
      for (let j = 0; j < d; j++) gw[j] += g * Z[i][j];
      gb += g;
    }
    for (let j = 0; j < d; j++) w[j] -= (lr * gw[j]) / n;
    b -= (lr * gb) / n;
  }
  return { mu, sd, w, b };
}

const score = (m: Model, x: number[]): number => 1 / (1 + Math.exp(-(x.reduce((a, v, j) => a + ((v - m.mu[j]) / m.sd[j]) * m.w[j], 0) + m.b)));

function streamScores(m: Model, y: Float32Array): number[] {
  // 흘러 들어온 소리를 0.08초 조각씩 받아, 조각마다 최근 0.4초 창의 점수 하나 (처음 4조각은 아직 창이 안 차서 0)
  const feats = frameFeats(y);
  const out = new Array(WIN - 1).fill(0);
  for (let i = WIN - 1; i < feats.length; i++) out.push(score(m, feats.slice(i - WIN + 1, i + 1).flat()));
  return out;
}

function detect(scores: number[], thr: number, need = 2, rest = 19): number[] {
  // 점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각(약 1.5초)은 쉬는 시간 → 깨어난 조각 번호들
  const fires: number[] = [];
  let run = 0, cool = 0;
  scores.forEach((s, i) => {
    if (cool > 0) { cool--; return; }
    run = s > thr ? run + 1 : 0;
    if (run >= need) { fires.push(i); run = 0; cool = rest; }
  });
  return fires;
}

function makeStream(wakeAt = [37, 100], decoyAt = [70], n = 150): Float32Array {
  // 12초 소리: 잡음 위에 깨움말 2번(약 3.0초 · 8.0초)과 비슷한 소리 1번(5.6초)
  const y = noise(n * FRAME);
  const put = (at: number, freqs: number[]): void => { const t = tones(freqs); for (let i = 0; i < t.length; i++) y[at * FRAME + i] += t[i]; };
  wakeAt.forEach((at) => put(at, WAKE));
  decoyAt.forEach((at) => put(at, DECOYS[0]));
  return y;
}

function voicedFrames(y: Float32Array, thr = 0.05): boolean[] {
  // 조각마다 소리 크기(RMS)가 문턱을 넘으면 '말하는 중'
  const out: boolean[] = [];
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    let e = 0;
    for (let n = 0; n < FRAME; n++) e += y[s + n] * y[s + n];
    out.push(Math.sqrt(e / FRAME) > thr);
  }
  return out;
}

function runMachine(fires: number[], voiced: boolean[], quietNeed = 5, giveUp = 25, think = 3, speak = 20): [number, string][] {
  // 비서의 상태: 대기 → (깨움말) 듣기 → (말이 끝남) 생각 → 말하기 → 대기. 말하는 중에 깨움말이 다시 오면 끊고 듣기로(barge-in)
  let state = "wait";
  const log: [number, string][] = [[0, "wait"]];
  let heard = 0, quiet = 0, left = 0, t0 = 0;
  voiced.forEach((v, i) => {
    const fired = fires.includes(i), before = state;
    if (state === "wait") {
      if (fired) { state = "listen"; heard = 0; quiet = 0; t0 = i; }
    } else if (state === "listen") {
      if (v) { heard++; quiet = 0; } else if (heard) quiet++;
      if (heard && quiet >= quietNeed) { state = "think"; left = think; }
      else if (!heard && i - t0 > giveUp) state = "wait"; // 아무 말도 없으면 포기하고 대기로
    } else if (state === "think") {
      left--;
      if (left === 0) { state = "speak"; left = speak; }
    } else if (state === "speak") {
      if (fired) { state = "listen"; heard = 0; quiet = 0; t0 = i; }
      else { left--; if (left === 0) state = "wait"; }
    }
    if (state !== before) log.push([i, state]);
  });
  return log;
}

function makeTalk(): Float32Array {
  // 깨움말(10~14조각) → 손님 말(20~34조각) → 비서가 말하는 중 깨움말 다시(52~56조각)
  const y = noise(110 * FRAME);
  const put = (at: number, freqs: number[]): void => { const t = tones(freqs); for (let i = 0; i < t.length; i++) y[at * FRAME + i] += t[i]; };
  put(10, WAKE);
  put(20, [C, C, C, C, C]); put(25, [C, C, C, C, C]); put(30, [C, C, C, C, C]);
  put(52, WAKE);
  return y;
}

type Part = { size_mb: number; ram_mb: number; load_s: number; rtf: number };
const BUDGET: Part = { size_mb: 300, ram_mb: 512, load_s: 5.0, rtf: 0.5 }; // 기기(저가 단말, 가상)의 예산. rtf = 처리 시간 ÷ 소리 길이 (1 이하여야 실시간)
const PARTS: Record<string, Part> = { // 부품별 잰 값 (예시 숫자: 진짜 모델을 내려받아 재는 대신 표로 둠)
  "깨움말": { size_mb: 0.02, ram_mb: 5, load_s: 0.1, rtf: 0.02 },
  "ASR small fp32": { size_mb: 970, ram_mb: 1800, load_s: 9.0, rtf: 1.4 },
  "ASR base int8": { size_mb: 78, ram_mb: 300, load_s: 1.5, rtf: 0.25 },
  TTS: { size_mb: 60, ram_mb: 200, load_s: 1.0, rtf: 0.15 },
};
const KEYS = ["size_mb", "ram_mb", "load_s", "rtf"] as const;

// 예산을 넘은 항목 이름들 (같은 키끼리 비교)
const overBudget = (measured: Part, budget: Part): string[] => KEYS.filter((k) => measured[k] > budget[k]).sort();

function total(names: string[]): Part {
  // 고른 부품을 한 기기에 함께 올릴 때: 크기 · 메모리 · 올리는 시간 · rtf 는 모두 더함(차례로 돌리므로)
  const t = { size_mb: 0, ram_mb: 0, load_s: 0, rtf: 0 };
  for (const n of names) for (const k of KEYS) t[k] += PARTS[n][k];
  return t;
}

function measureToy(): number {
  // 진짜로 재 보기: 12초 합성 소리에서 조각마다 띠 에너지를 뽑는 데 걸린 시간 ÷ 12초 (rtf)
  const y = Float32Array.from({ length: 12 * SR }, (_, i) => 0.1 * Math.sin(i * 0.37) * (((i * 7919) % 13) / 13));
  const t0 = performance.now();
  let sink = 0;
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    for (let band = 0; band < 8; band++) {
      let re = 0, im = 0;
      const w = (2 * Math.PI * (band * 500 + 250)) / SR;
      for (let n = 0; n < FRAME; n++) { re += y[s + n] * Math.cos(w * n); im -= y[s + n] * Math.sin(w * n); }
      sink += Math.log(re * re + im * im + 1e-9);
    }
  }
  return (performance.now() - t0) / 1000 / 12 + (sink === Infinity ? 1 : 0);
}

function choose(offline: boolean, privacyHigh: boolean, needsBigLlm: boolean, latencyMs: number): [string, string] {
  // 클라우드 · 기기 · 섞기 중 고르기: 위에서부터 먼저 맞는 규칙이 이긴다 → [고른 것, 이유]
  if (offline) return ["device", "인터넷이 없어도 돌아야 함"];
  if (needsBigLlm && privacyHigh) return ["hybrid", "깨움말 · 받아쓰기는 기기, 생각은 클라우드(개인정보는 가려서)"];
  if (needsBigLlm) return ["cloud", "큰 LLM이 필요함"];
  if (privacyHigh) return ["device", "소리가 기기 밖으로 나가면 안 됨"];
  if (latencyMs < 300) return ["device", "네트워크 왕복 시간을 쓸 수 없음"];
  return ["cloud", "특별한 제약이 없으면 관리가 쉬운 클라우드"];
}

// 기기를 한 대 사는 돈(원)이 클라우드 통화 요금(원)과 같아지는 통화 수 (올림, 정수)
const breakEvenCalls = (deviceWon: number, cloudWonPerCall: number): number => Math.ceil(deviceWon / cloudWonPerCall);

const model = train(...makeData(120)); // 1) 작은 깨움말 분류기 (진짜 TTS · sherpa-onnx 대신 합성 소리)
const y = makeTalk();
const fires = detect(streamScores(model, y), 0.9); // 2) 0.08초 조각마다 점수 → 연속 확인 + 쉬는 시간
const log = runMachine(fires, voicedFrames(y)); // 3) 비서의 상태
console.log("깨움말 감지:", JSON.stringify(fires), "| 상태:", log.map(([, s]) => s).join(" → "));

const setA = ["깨움말", "ASR small fp32", "TTS"], setB = ["깨움말", "ASR base int8", "TTS"];
const overA = overBudget(total(setA), BUDGET), overB = overBudget(total(setB), BUDGET); // 4) 기기 예산
console.log(`예산 A (small fp32): 넘은 항목 ${overA.join(", ") || "없음"}`);
console.log(`예산 B (base int8): 넘은 항목 ${overB.join(", ") || "없음"}`);
const toy = measureToy();
console.log(`장난감 앞단의 rtf ${toy.toFixed(4)} (예산 ${BUDGET.rtf} 이하여야 실시간)`);
const c1 = choose(false, true, true, 500), c2 = choose(true, false, true, 1000); // 5) 클라우드 · 기기 선택
console.log("선택:", c1, c2, "| 손익분기 통화 수", breakEvenCalls(30000, 8));
check(JSON.stringify(fires) === "[14,56]" && log.map(([, s]) => s).join() === "wait,listen,think,speak,listen,wait" && overA.join() === "load_s,ram_mb,rtf,size_mb" && overB.length === 0
  && toy < BUDGET.rtf && c1[0] === "hybrid" && c2[0] === "device" && breakEvenCalls(30000, 8) === 3750,
  "깨움말 2번 감지, 상태 순서, fp32 조합은 예산 초과 · int8 조합은 통과, 개인정보+큰 LLM은 hybrid, 오프라인은 device 여야 해요.");

budget.typescript:
