for (const [name, m] of Object.entries(PARTS)) console.log(`${name.padEnd(15)} | 넘은 항목: ${overBudget(m, BUDGET).join(", ") || "없음"}`);
check(overBudget({ size_mb: 900, ram_mb: 100, load_s: 1.0, rtf: 0.9 }, BUDGET).join() === "rtf,size_mb" && overBudget(PARTS.TTS, BUDGET).length === 0, "예산보다 큰 항목 이름만, 이름순으로 돌려줘야 해요.");

const A = total(["깨움말", "ASR small fp32", "TTS"]), B = total(["깨움말", "ASR base int8", "TTS"]);
console.log("조합 A (small fp32):", JSON.stringify(A), "→ 넘음", overBudget(A, BUDGET).join(", "));
console.log("조합 B (base int8):", JSON.stringify(B), "→ 넘음", overBudget(B, BUDGET).join(", ") || "없음");
check(overBudget(A, BUDGET).join() === "load_s,ram_mb,rtf,size_mb" && overBudget(B, BUDGET).length === 0, "fp32 조합은 네 가지 모두 넘고, int8 조합은 모두 예산 안이어야 해요.");

const toy = measureToy();
console.log(`장난감 앞단: 12초 소리를 처리하는 데 걸린 시간 ÷ 12초 = rtf ${toy.toFixed(5)}`);
check(toy < BUDGET.rtf, "rtf가 예산(0.5) 안이어야 실시간으로 쓸 수 있어요.");

stream.typescript:
// D44 · Part 1 · 스트리밍과 말 끝 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_stream.ts
//   소리를 0.08초 조각씩 받아도 한 번에 처리한 것과 결과가 같고, 말 끝을 판단하는 조용한 조각 수는 '말 속 쉼에서 끊기지 않기'와 '답이 빨리 오기'의 균형
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const FRAME = 1280; // 0.08초 조각

function build(pauseFrames: number): Float32Array {
  // 합성 소리: 잡음 → 말 10조각 → 말 속 쉼 pauseFrames조각 → 말 8조각 → 긴 잡음 (말 = 1200 Hz 소리)
  let seed = 1;
  const noise = (n: number): Float32Array => Float32Array.from({ length: n * FRAME }, () => { seed = (seed * 1103515245 + 12345) % 2147483648; return ((seed / 2147483648) * 2 - 1) * 0.02; });
  const speech = (n: number): Float32Array => Float32Array.from({ length: n * FRAME }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 1200 * i) / SR));
  const parts = [noise(8), speech(10), noise(pauseFrames), speech(8), noise(12)];
  const y = new Float32Array(parts.reduce((a, p) => a + p.length, 0));
  let at = 0;
  for (const p of parts) { y.set(p, at); at += p.length; }
  return y;
}

class Framer {
  // 스트리밍 받이: 아무 크기로 들어오는 소리를 쌓았다가 0.08초 조각이 찰 때마다 RMS를 내보낸다
  buf = new Float32Array(0);
  push(x: Float32Array): number[] {
    const b = new Float32Array(this.buf.length + x.length);
    b.set(this.buf); b.set(x, this.buf.length);
    const k = Math.floor(b.length / FRAME);
    const out: number[] = [];
    for (let i = 0; i < k; i++) {
      let e = 0;
      for (let n = 0; n < FRAME; n++) e += b[i * FRAME + n] ** 2;
      out.push(Math.sqrt(e / FRAME));
    }
    this.buf = b.slice(k * FRAME);
    return out;
  }
}

function endpoints(voiced: boolean[], need: number): [number, number][] {
  // 말 끝 판단: 조용한 조각이 need개 이어지면 말이 끝났다고 보고 → [시작 조각, 끝났다고 알아챈 조각]
  const out: [number, number][] = [];
  let start = -1, quiet = 0;
  voiced.forEach((v, i) => {
    if (v) { if (start < 0) start = i; quiet = 0; }
    else if (start >= 0 && ++quiet >= need) { out.push([start, i]); start = -1; quiet = 0; }
  });
  return out;
}

const y = build(4); // 말 중간에 0.32초 쉼이 있는 문장
const f = new Framer();
const rmsStream: number[] = [];
let pos = 0, k = 0;
while (pos < y.length) { // 700 · 1900 · 3333 샘플씩 제멋대로 들어오는 소리
  const size = [700, 1900, 3333][k % 3];
  rmsStream.push(...f.push(y.slice(pos, pos + size)));
  pos += size; k++;
}
const rmsBatch = new Framer().push(y);
check(rmsStream.length === rmsBatch.length && rmsStream.every((v, i) => Math.abs(v - rmsBatch[i]) < 1e-6), "조각으로 나눠 받아도 한 번에 계산한 것과 같아야 해요.");

const voiced = rmsBatch.map((r) => r > 0.05);
const counts: Record<number, number> = {};
for (const need of [2, 3, 4, 5, 6, 8]) {
  counts[need] = endpoints(voiced, need).length;
  console.log(`조용한 조각 ${need}개(${((need * FRAME) / SR).toFixed(2)}초) 기다림 → 문장 ${counts[need]}개로 나눔`);
}
const need = Object.keys(counts).map(Number).find((n) => counts[n] === 1)!;
console.log(`쉼을 넘기려면 최소 ${need}조각 → 말이 끝나고 ${((need * FRAME) / SR).toFixed(2)}초 뒤에야 답을 시작할 수 있다`);
check(counts[3] === 2 && counts[4] === 2 && need === 5, "쉼이 4조각이니 4조각 이하로 기다리면 문장이 둘로 잘리고, 5조각부터 하나여야 해요.");

quant.typescript:
// D44 · Part 2 · 양자화 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_quant.ts
//   32비트 실수 가중치를 8비트 정수로(대칭 int8 · 비대칭 uint8): 오차는 눈금의 절반 이하, 크기는 1/4, int8 파일은 눈금 4바이트 + 정수 한 바이트씩
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function quantize(w: Float32Array): [Int8Array, number] {
  // 대칭 int8: 가장 큰 값을 127에 맞춘다 → [정수 배열, 눈금 scale]
  const scale = w.reduce((m, v) => Math.max(m, Math.abs(v)), 0) / 127;
  return [Int8Array.from(w, (v) => Math.round(v / scale)), scale];
}
const dequantize = (q: Int8Array, scale: number): Float32Array => Float32Array.from(q, (v) => v * Math.fround(scale));

function quantizeAffine(x: Float32Array): [Uint8Array, number, number] {
  // 비대칭 uint8(활성값처럼 0 이상일 때): 최소를 0, 최대를 255에 맞추고 영점(zero point)을 기억
  const lo = x.reduce((m, v) => Math.min(m, v), Infinity), hi = x.reduce((m, v) => Math.max(m, v), -Infinity);
  const scale = (hi - lo) / 255;
  const zp = Math.round(-lo / scale);
  return [Uint8Array.from(x, (v) => Math.min(255, Math.max(0, Math.round(v / scale) + zp))), scale, zp];
}

function pack(q: Int8Array, scale: number): Uint8Array {
  // int8 파일의 속: 앞 4바이트 = float32 눈금, 그 뒤 = 정수 한 바이트씩
  const buf = new Uint8Array(4 + q.length);
  new DataView(buf.buffer).setFloat32(0, scale, true);
  buf.set(new Uint8Array(q.buffer, q.byteOffset, q.length), 4);
  return buf;
}
function unpack(buf: Uint8Array): [Int8Array, number] {
  const scale = new DataView(buf.buffer, buf.byteOffset).getFloat32(0, true);
  return [new Int8Array(buf.slice(4).buffer), scale];
}

let seed = 3;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
const w = Float32Array.from({ length: 1000 }, () => (rand() * 2 - 1) * 0.17); // 작은 모델의 가중치 (장난감)
const [q, scale] = quantize(w);
const back = dequantize(q, scale);
const err = w.reduce((m, v, i) => Math.max(m, Math.abs(back[i] - v)), 0);
console.log(`눈금 ${scale.toFixed(6)} | 최대 오차 ${err.toFixed(6)} (눈금의 절반 ${(scale / 2).toFixed(6)}) | q 범위 ${Math.min(...q)}~${Math.max(...q)}`);
check(err <= scale / 2 + 1e-7 && Math.min(...q) >= -127 && Math.max(...q) <= 127, "되돌린 값의 오차는 눈금의 절반 이하, 정수는 -127~127 이어야 해요.");

const buf = pack(q, scale);
const [q2, s2] = unpack(buf);
console.log(`float32 ${w.byteLength}바이트 → int8 파일 ${buf.length}바이트 (${(w.byteLength / buf.length).toFixed(2)}배 작음)`);
check(q.every((v, i) => v === q2[i]) && s2 === Math.fround(scale) && buf.length === 4 + w.length, "파일에서 읽어도 정수와 눈금이 같고, 크기는 4 + 개수 바이트여야 해요.");

const x = Float32Array.from({ length: 1000 }, () => rand() * 6); // 0 이상인 활성값
const [qa, sa, zp] = quantizeAffine(x);
const errA = x.reduce((m, v, i) => Math.max(m, Math.abs((qa[i] - zp) * sa - v)), 0);
console.log(`비대칭 uint8: 눈금 ${sa.toFixed(5)} · 영점 ${zp} · 최대 오차 ${errA.toFixed(5)}`);
check(errA <= sa / 2 + 1e-6, "비대칭 양자화의 오차도 눈금의 절반 이하여야 해요.");

const feat = Float32Array.from({ length: 1000 }, () => rand() * 2 - 1);
const dot = (a: Float32Array): number => a.reduce((s, v, i) => s + v * feat[i], 0);
console.log(`점수 ${dot(w).toFixed(4)} → 양자화 뒤 ${dot(back).toFixed(4)}`);
check(Math.abs(dot(w) - dot(back)) < 0.05 * Math.max(1, Math.abs(dot(w))), "양자화해도 점수는 거의 그대로여야 해요.");

wake.typescript:
// D44 · Part 3 · 깨움말의 구조 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_wake.ts
//   얼어 있는 앞단(8개 띠 로그 에너지) + 작은 분류기(로지스틱 회귀)로 '하나야' 흉내 소리(합성)를 알아듣게 학습하고, 처음 듣는 소리로 시험
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const FRAME = 1280; // 0.08초 조각 = 스트리밍의 한 걸음
const WIN = 5; // 0.4초 = 조각 5개를 이어서 본다
const CENTERS = Array.from({ length: 8 }, (_, i) => i * 500 + 250); // 얼어 있는 앞단: 주파수 띠 8개의 가운데 (250, 750, ... 3750 Hz)
const [A, B, C] = [750, 1750, 2750]; // 낮은 소리 · 높은 소리 · 더 높은 소리
const WAKE = [A, A, B, B, B]; // "하나야" 흉내(합성 신호): 낮은 소리 2조각 → 높은 소리 3조각
const DECOYS = [[B, B, A, A, A], [A, A, A, A, A], [C, C, C, C, C], [A, B, A, B, A], [B, B, B, B, B], [C, C, A, A, A]]; // 비슷하지만 다른 소리

let seed = 2024;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }; // 0~1 (재현 가능한 난수)
const uni = (lo: number, hi: number): number => lo + (hi - lo) * rand();

function frameFeats(y: Float32Array): number[][] {
  // 앞단(학습하지 않음): 0.08초 조각마다 8개 띠의 로그 에너지 → (조각 수, 8)
  const out: number[][] = [];
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    out.push(CENTERS.map((fc) => {
      let re = 0, im = 0;
      for (let n = 0; n < FRAME; n++) { const ph = (2 * Math.PI * fc * n) / SR; re += y[s + n] * Math.cos(ph); im -= y[s + n] * Math.sin(ph); }
      return Math.log((re * re + im * im) / (FRAME * FRAME) + 1e-9);
    }));
  }
  return out;
}

function tones(freqs: number[], jitter = 30, amp = 0.3): Float32Array {
  const y = new Float32Array(freqs.length * FRAME);
  freqs.forEach((f0, k) => {
    const f = f0 + uni(-jitter, jitter), a = amp * uni(0.8, 1.2), ph = uni(0, 6.28);
    for (let n = 0; n < FRAME; n++) y[k * FRAME + n] = a * Math.sin(2 * Math.PI * f * (n / SR) + ph);
  });
  return y;
}
const noise = (n: number, amp = 0.02): Float32Array => Float32Array.from({ length: n }, () => uni(-1, 1) * amp);

function windowSample(freqs: number[], shift = 0): number[] {
  // 소리 5조각(앞뒤 잡음 포함)에서 shift 조각 어긋난 0.4초 창을 잘라 특징 40개로
  const y = noise(9 * FRAME);
  y.set(tones(freqs).map((v, i) => v + y[2 * FRAME + i]), 2 * FRAME);
  return frameFeats(y.slice((2 + shift) * FRAME, (2 + shift + WIN) * FRAME)).flat();
}

function makeData(n: number): [number[][], number[]] {
  // 깨움말 창 (정확히 맞은 것 + 한 조각 어긋난 것)을 정답(1), 비슷한 소리 · 잡음 창을 오답(0)으로
  const X: number[][] = [], y: number[] = [];
  const shifts = [0, -1, 1];
  for (let i = 0; i < n; i++) {
    X.push(windowSample(WAKE, shifts[i % 3])); y.push(1);
    X.push(windowSample(DECOYS[i % DECOYS.length], shifts[Math.floor(i / 2) % 3])); y.push(0);
    X.push(frameFeats(noise(WIN * FRAME)).flat()); y.push(0);
  }
  return [X, y];
}

interface Model { mu: number[]; sd: number[]; w: number[]; b: number }
function train(X: number[][], y: number[], epochs = 400, lr = 0.5): Model {
  // 작은 분류기: 표준화 + 로지스틱 회귀 (장난감 모델, 학습은 순식간)
  const d = X[0].length, n = X.length;
  const mu = Array.from({ length: d }, (_, j) => X.reduce((a, r) => a + r[j], 0) / n);
  const sd = Array.from({ length: d }, (_, j) => Math.sqrt(X.reduce((a, r) => a + (r[j] - mu[j]) ** 2, 0) / n) + 1e-6);
  const Z = X.map((r) => r.map((v, j) => (v - mu[j]) / sd[j]));
  const w = new Array(d).fill(0);
  let b = 0;
  for (let e = 0; e < epochs; e++) {
    const gw = new Array(d).fill(0);
    let gb = 0;
    for (let i = 0; i < n; i++) {
      const g = 1 / (1 + Math.exp(-(Z[i].reduce((a, v, j) => a + v * w[j], 0) + b))) - y[i];
      for (let j = 0; j < d; j++) gw[j] += g * Z[i][j];
      gb += g;
    }
    for (let j = 0; j < d; j++) w[j] -= (lr * gw[j]) / n;
    b -= (lr * gb) / n;
  }
  return { mu, sd, w, b };
}

const score = (m: Model, x: number[]): number => 1 / (1 + Math.exp(-(x.reduce((a, v, j) => a + ((v - m.mu[j]) / m.sd[j]) * m.w[j], 0) + m.b)));

function streamScores(m: Model, y: Float32Array): number[] {
  // 흘러 들어온 소리를 0.08초 조각씩 받아, 조각마다 최근 0.4초 창의 점수 하나 (처음 4조각은 아직 창이 안 차서 0)
  const feats = frameFeats(y);
  const out = new Array(WIN - 1).fill(0);
  for (let i = WIN - 1; i < feats.length; i++) out.push(score(m, feats.slice(i - WIN + 1, i + 1).flat()));
  return out;
}

function detect(scores: number[], thr: number, need = 2, rest = 19): number[] {
  // 점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각(약 1.5초)은 쉬는 시간 → 깨어난 조각 번호들
  const fires: number[] = [];
  let run = 0, cool = 0;
  scores.forEach((s, i) => {
    if (cool > 0) { cool--; return; }
    run = s > thr ? run + 1 : 0;
    if (run >= need) { fires.push(i); run = 0; cool = rest; }
  });
  return fires;
}

function makeStream(wakeAt = [37, 100], decoyAt = [70], n = 150): Float32Array {
  // 12초 소리: 잡음 위에 깨움말 2번(약 3.0초 · 8.0초)과 비슷한 소리 1번(5.6초)
  const y = noise(n * FRAME);
  const put = (at: number, freqs: number[]): void => { const t = tones(freqs); for (let i = 0; i < t.length; i++) y[at * FRAME + i] += t[i]; };
  wakeAt.forEach((at) => put(at, WAKE));
  decoyAt.forEach((at) => put(at, DECOYS[0]));
  return y;
}

const [X, y] = makeData(120); // 학습 데이터: 깨움말 120개 + 비슷한 소리·잡음 240개 (모두 합성)
const model = train(X, y);
const [Xt, yt] = makeData(60); // 처음 듣는 소리(다른 난수)로 시험
const p = Xt.map((x) => score(model, x));
const acc = p.filter((v, i) => (v > 0.5 ? 1 : 0) === yt[i]).length / yt.length;
const mean = (xs: number[]): number => xs.reduce((a, v) => a + v, 0) / xs.length;
console.log(`앞단 특징 ${X[0].length}개(8띠 × 5조각) · 학습 ${y.length}개 · 시험 ${yt.length}개 정확도 ${(acc * 100).toFixed(1)}%`);
const pPos = mean(p.filter((_, i) => yt[i] === 1)), pNeg = mean(p.filter((_, i) => yt[i] === 0));
console.log(`깨움말 점수 평균 ${pPos.toFixed(2)} · 비슷한 소리·잡음 점수 평균 ${pNeg.toFixed(2)}`);
check(acc >= 0.95, "처음 듣는 소리에서도 정확도 95% 이상이어야 해요.");
check(pPos > 0.9 && pNeg < 0.1, "깨움말은 평균 0.9 위, 나머지는 0.1 아래여야 해요.");

thresh.typescript:
// D44 · Part 3 · 문턱과 오작동 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_thresh.ts
//   문턱을 올리면 엉뚱하게 깨어남(FAR)은 줄고 못 깨어남(FRR)은 늘어난다 + 한 조각만 높은 소리는 '연속 확인'으로 걸러 오작동을 막는다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const FRAME = 1280; // 0.08초 조각 = 스트리밍의 한 걸음
const WIN = 5; // 0.4초 = 조각 5개를 이어서 본다
const CENTERS = Array.from({ length: 8 }, (_, i) => i * 500 + 250); // 얼어 있는 앞단: 주파수 띠 8개의 가운데 (250, 750, ... 3750 Hz)
const [A, B, C] = [750, 1750, 2750]; // 낮은 소리 · 높은 소리 · 더 높은 소리
const WAKE = [A, A, B, B, B]; // "하나야" 흉내(합성 신호): 낮은 소리 2조각 → 높은 소리 3조각
const DECOYS = [[B, B, A, A, A], [A, A, A, A, A], [C, C, C, C, C], [A, B, A, B, A], [B, B, B, B, B], [C, C, A, A, A]]; // 비슷하지만 다른 소리

let seed = 2024;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }; // 0~1 (재현 가능한 난수)
const uni = (lo: number, hi: number): number => lo + (hi - lo) * rand();

function frameFeats(y: Float32Array): number[][] {
  // 앞단(학습하지 않음): 0.08초 조각마다 8개 띠의 로그 에너지 → (조각 수, 8)
  const out: number[][] = [];
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    out.push(CENTERS.map((fc) => {
      let re = 0, im = 0;
      for (let n = 0; n < FRAME; n++) { const ph = (2 * Math.PI * fc * n) / SR; re += y[s + n] * Math.cos(ph); im -= y[s + n] * Math.sin(ph); }
      return Math.log((re * re + im * im) / (FRAME * FRAME) + 1e-9);
    }));
  }
  return out;
}

function tones(freqs: number[], jitter = 30, amp = 0.3): Float32Array {
  const y = new Float32Array(freqs.length * FRAME);
  freqs.forEach((f0, k) => {
    const f = f0 + uni(-jitter, jitter), a = amp * uni(0.8, 1.2), ph = uni(0, 6.28);
    for (let n = 0; n < FRAME; n++) y[k * FRAME + n] = a * Math.sin(2 * Math.PI * f * (n / SR) + ph);
  });
  return y;
}
const noise = (n: number, amp = 0.02): Float32Array => Float32Array.from({ length: n }, () => uni(-1, 1) * amp);

function windowSample(freqs: number[], shift = 0): number[] {
  // 소리 5조각(앞뒤 잡음 포함)에서 shift 조각 어긋난 0.4초 창을 잘라 특징 40개로
  const y = noise(9 * FRAME);
  y.set(tones(freqs).map((v, i) => v + y[2 * FRAME + i]), 2 * FRAME);
  return frameFeats(y.slice((2 + shift) * FRAME, (2 + shift + WIN) * FRAME)).flat();
}

function makeData(n: number): [number[][], number[]] {
  // 깨움말 창 (정확히 맞은 것 + 한 조각 어긋난 것)을 정답(1), 비슷한 소리 · 잡음 창을 오답(0)으로
  const X: number[][] = [], y: number[] = [];
  const shifts = [0, -1, 1];
  for (let i = 0; i < n; i++) {
    X.push(windowSample(WAKE, shifts[i % 3])); y.push(1);
    X.push(windowSample(DECOYS[i % DECOYS.length], shifts[Math.floor(i / 2) % 3])); y.push(0);
    X.push(frameFeats(noise(WIN * FRAME)).flat()); y.push(0);
  }
  return [X, y];
}

interface Model { mu: number[]; sd: number[]; w: number[]; b: number }
function train(X: number[][], y: number[], epochs = 400, lr = 0.5): Model {
  // 작은 분류기: 표준화 + 로지스틱 회귀 (장난감 모델, 학습은 순식간)
  const d = X[0].length, n = X.length;
  const mu = Array.from({ length: d }, (_, j) => X.reduce((a, r) => a + r[j], 0) / n);
  const sd = Array.from({ length: d }, (_, j) => Math.sqrt(X.reduce((a, r) => a + (r[j] - mu[j]) ** 2, 0) / n) + 1e-6);
  const Z = X.map((r) => r.map((v, j) => (v - mu[j]) / sd[j]));
  const w = new Array(d).fill(0);
  let b = 0;
  for (let e = 0; e < epochs; e++) {
    const gw = new Array(d).fill(0);
    let gb = 0;
    for (let i = 0; i < n; i++) {
      const g = 1 / (1 + Math.exp(-(Z[i].reduce((a, v, j) => a + v * w[j], 0) + b))) - y[i];
      for (let j = 0; j < d; j++) gw[j] += g * Z[i][j];
      gb += g;
    }
    for (let j = 0; j < d; j++) w[j] -= (lr * gw[j]) / n;
    b -= (lr * gb) / n;
  }
  return { mu, sd, w, b };
}

const score = (m: Model, x: number[]): number => 1 / (1 + Math.exp(-(x.reduce((a, v, j) => a + ((v - m.mu[j]) / m.sd[j]) * m.w[j], 0) + m.b)));

function streamScores(m: Model, y: Float32Array): number[] {
  // 흘러 들어온 소리를 0.08초 조각씩 받아, 조각마다 최근 0.4초 창의 점수 하나 (처음 4조각은 아직 창이 안 차서 0)
  const feats = frameFeats(y);
  const out = new Array(WIN - 1).fill(0);
  for (let i = WIN - 1; i < feats.length; i++) out.push(score(m, feats.slice(i - WIN + 1, i + 1).flat()));
  return out;
}

function detect(scores: number[], thr: number, need = 2, rest = 19): number[] {
  // 점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각(약 1.5초)은 쉬는 시간 → 깨어난 조각 번호들
  const fires: number[] = [];
  let run = 0, cool = 0;
  scores.forEach((s, i) => {
    if (cool > 0) { cool--; return; }
    run = s > thr ? run + 1 : 0;
    if (run >= need) { fires.push(i); run = 0; cool = rest; }
  });
  return fires;
}

function makeStream(wakeAt = [37, 100], decoyAt = [70], n = 150): Float32Array {
  // 12초 소리: 잡음 위에 깨움말 2번(약 3.0초 · 8.0초)과 비슷한 소리 1번(5.6초)
  const y = noise(n * FRAME);
  const put = (at: number, freqs: number[]): void => { const t = tones(freqs); for (let i = 0; i < t.length; i++) y[at * FRAME + i] += t[i]; };
  wakeAt.forEach((at) => put(at, WAKE));
  decoyAt.forEach((at) => put(at, DECOYS[0]));
  return y;
}

const model = train(...makeData(240)); // 학습 데이터를 넉넉히(깨움말 240 + 나머지 480) — 적으면 비슷한 소리에 속는 문턱이 생김
const [Xt, yt] = makeData(60);
const p = Xt.map((x) => score(model, x));
const rate = (pred: (s: number) => boolean, label: number): number => {
  const xs = p.filter((_, i) => yt[i] === label);
  return xs.filter(pred).length / xs.length;
};
const rows: [number, number, number][] = [];
for (const thr of [0.5, 0.7, 0.9, 0.95, 0.99]) {
  const frr = rate((s) => s <= thr, 1), far = rate((s) => s > thr, 0);
  rows.push([thr, frr, far]);
  console.log(`문턱 ${thr.toFixed(2)} | 못 깨어남(FRR) ${(frr * 100).toFixed(1)}% | 엉뚱하게 깨어남(FAR) ${(far * 100).toFixed(1)}%`);
}
check(rows.every((r, i) => i === 0 || (rows[i - 1][1] <= r[1] && rows[i - 1][2] >= r[2])), "문턱을 올리면 FRR은 늘기만, FAR은 줄기만 해야 해요.");
const best = rows.find((r) => r[2] === 0)!;
console.log(`FAR이 0이 되는 가장 낮은 문턱 ${best[0]} (FRR ${(best[1] * 100).toFixed(1)}%)`);
check(best[1] <= 0.15, "엉뚱하게 깨어나지 않는 문턱에서도 FRR은 15% 이하여야 해요.");

// 흘러 들어오는 소리(12초): 깨움말 2번 + 비슷한 소리(B B A A A) 1번. 한 조각만 높게 나온 것은 연속 확인으로 걸러낸다
const scores = streamScores(model, makeStream());
const once = detect(scores, 0.9, 1), twice = detect(scores, 0.9, 2); // 문턱 0.9로 고정
console.log(`한 조각만 넘어도 깨어남: ${once.length}번 ${JSON.stringify(once)} | 연속 2조각 확인: ${twice.length}번 ${JSON.stringify(twice)}`);
check(once.length === 3 && twice.length === 2, "연속 확인을 쓰면 비슷한 소리에 깨어나지 않고 깨움말 2번만 잡아야 해요.");

states.python:
# D44 · Part 4 · 비서의 상태 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d44_states.py   (모의 부품만 써요 · 인터넷·GPU·Docker·마이크 불필요)
#   깨움말 → 듣기 → (말이 끝나면) 생각 → 말하기 → 대기 상태 기계: 말하는 중 깨움말이 다시 오면 끊고 듣기로(barge-in), 아무 말이 없으면 포기하고 대기로
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import numpy as np

SR = 16000                                     # 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
FRAME = 1280                                   # 0.08초 조각 = 스트리밍의 한 걸음
WIN = 5                                        # 0.4초 = 조각 5개를 이어서 본다
CENTERS = np.arange(8) * 500 + 250             # 얼어 있는 앞단: 주파수 띠 8개의 가운데 (250, 750, ... 3750 Hz)
_E = np.exp(-2j * np.pi * CENTERS[:, None] * np.arange(FRAME) / SR)
A, B, C = 750, 1750, 2750                      # 낮은 소리 · 높은 소리 · 더 높은 소리
WAKE = [A, A, B, B, B]                         # "하나야" 흉내(합성 신호): 낮은 소리 2조각 → 높은 소리 3조각
DECOYS = [[B, B, A, A, A], [A] * 5, [C] * 5, [A, B, A, B, A], [B] * 5, [C, C, A, A, A]]   # 비슷하지만 다른 소리


def frame_feats(y):
    """앞단(학습하지 않음): 0.08초 조각마다 8개 띠의 로그 에너지 → (조각 수, 8)"""
    f = y[: len(y) // FRAME * FRAME].reshape(-1, FRAME)
    return np.log(np.abs(f @ _E.T) ** 2 / FRAME ** 2 + 1e-9)


def tones(freqs, rng, jitter=30.0, amp=0.3):
    t = np.arange(FRAME) / SR
    return np.concatenate([amp * rng.uniform(0.8, 1.2) * np.sin(2 * np.pi * (f + rng.uniform(-jitter, jitter)) * t + rng.uniform(0, 6.28)) for f in freqs])


def noise(n, rng, amp=0.02):
    return rng.uniform(-1, 1, n) * amp


def window_sample(freqs, rng, shift=0):
    """소리 5조각(앞뒤 잡음 포함)에서 shift 조각 어긋난 0.4초 창을 잘라 특징 40개로"""
    y = np.concatenate([noise(2 * FRAME, rng), tones(freqs, rng), noise(2 * FRAME, rng)]) + noise(9 * FRAME, rng)
    return frame_feats(y[(2 + shift) * FRAME:(2 + shift + WIN) * FRAME]).reshape(-1)


def make_data(n, seed):
    """깨움말 창 (정확히 맞은 것 + 한 조각 어긋난 것)을 정답(1), 비슷한 소리 · 잡음 창을 오답(0)으로"""
    rng = np.random.default_rng(seed)
    X, y = [], []
    for i in range(n):
        X.append(window_sample(WAKE, rng, shift=(0, -1, 1)[i % 3])); y.append(1)
        X.append(window_sample(DECOYS[i % len(DECOYS)], rng, shift=(0, -1, 1)[(i // 2) % 3])); y.append(0)
        X.append(frame_feats(noise(WIN * FRAME, rng)).reshape(-1)); y.append(0)
    return np.array(X), np.array(y)


def train(X, y, epochs=400, lr=0.5):
    """작은 분류기: 표준화 + 로지스틱 회귀 (장난감 모델, 학습은 순식간)"""
    mu, sd = X.mean(0), X.std(0) + 1e-6
    Z = (X - mu) / sd
    w, b = np.zeros(Z.shape[1]), 0.0
    for _ in range(epochs):
        g = 1 / (1 + np.exp(-(Z @ w + b))) - y
        w -= lr * Z.T @ g / len(y)
        b -= lr * g.mean()
    return dict(mu=mu, sd=sd, w=w, b=b)


def score(model, x):
    return 1 / (1 + np.exp(-(((x - model["mu"]) / model["sd"]) @ model["w"] + model["b"])))


def stream_scores(model, y):
    """흘러 들어온 소리를 0.08초 조각씩 받아, 조각마다 최근 0.4초 창의 점수 하나 (처음 4조각은 아직 창이 안 차서 0)"""
    feats = frame_feats(y)
    return [0.0] * (WIN - 1) + [float(score(model, feats[i - WIN + 1:i + 1].reshape(-1))) for i in range(WIN - 1, len(feats))]


def detect(scores, thr, need=2, rest=19):
    """점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각(약 1.5초)은 쉬는 시간 → 깨어난 조각 번호들"""
    fires, run, cool = [], 0, 0
    for i, s in enumerate(scores):
        if cool > 0:
            cool -= 1
            continue
        run = run + 1 if s > thr else 0
        if run >= need:
            fires.append(i)
            run, cool = 0, rest
    return fires


def make_stream(rng, wake_at=(37, 100), decoy_at=(70,), n=150):
    """12초 소리: 잡음 위에 깨움말 2번(약 3.0초 · 8.0초)과 비슷한 소리 1번(5.6초)"""
    y = noise(n * FRAME, rng)
    for at in wake_at:
        y[at * FRAME:(at + WIN) * FRAME] += tones(WAKE, rng)
    for at in decoy_at:
        y[at * FRAME:(at + WIN) * FRAME] += tones(DECOYS[0], rng)
    return y

def voiced_frames(y, thr=0.05):
    """조각마다 소리 크기(RMS)가 문턱을 넘으면 '말하는 중'"""
    f = y[: len(y) // FRAME * FRAME].reshape(-1, FRAME)
    return [bool(v) for v in (np.sqrt((f ** 2).mean(1)) > thr)]


def run_machine(fires, voiced, quiet_need=5, give_up=25, think=3, speak=20):
    """비서의 상태: 대기 → (깨움말) 듣기 → (말이 끝남) 생각 → 말하기 → 대기. 말하는 중에 깨움말이 다시 오면 끊고 듣기로(barge-in)"""
    state, log = "wait", [(0, "wait")]
    heard = quiet = left = t0 = 0
    for i, v in enumerate(voiced):
        fired, before = i in fires, state
        if state == "wait":
            if fired:
                state, heard, quiet, t0 = "listen", 0, 0, i
        elif state == "listen":
            if v:
                heard, quiet = heard + 1, 0
            elif heard:
                quiet += 1
            if heard and quiet >= quiet_need:
                state, left = "think", think
            elif not heard and i - t0 > give_up:                 # 아무 말도 없으면 포기하고 대기로
                state = "wait"
        elif state == "think":
            left -= 1
            if left == 0:
                state, left = "speak", speak
        elif state == "speak":
            if fired:
                state, heard, quiet, t0 = "listen", 0, 0, i
            else:
                left -= 1
                if left == 0:
                    state = "wait"
        if state != before:
            log.append((i, state))
    return log

def make_talk(rng):
    """깨움말(10~14조각) → 손님 말(20~34조각) → 비서가 말하는 중 깨움말 다시(52~56조각)"""
    y = noise(110 * FRAME, rng)
    for at, freqs in [(10, WAKE), (20, [C] * 5), (25, [C] * 5), (30, [C] * 5), (52, WAKE)]:
        y[at * FRAME:(at + WIN) * FRAME] += tones(freqs, rng)
    return y

model = train(*make_data(120, seed=0))
y = make_talk(np.random.default_rng(7))
fires = detect(stream_scores(model, y), 0.9)
log = run_machine(set(fires), voiced_frames(y))
print("깨움말 감지 조각:", fires)
for i, s in log:
    print(f"{i * FRAME / SR:5.2f}초 → {s}")
check(fires == [14, 56], "깨움말은 14번째 조각(첫 번째)과 56번째 조각(말하는 중)에서만 감지돼야 해요.")
check([s for _, s in log] == ["wait", "listen", "think", "speak", "listen", "wait"], "대기 → 듣기 → 생각 → 말하기 → (끼어들기) 듣기 → 말이 없어 대기 순서여야 해요.")

# 깨움말 없이 손님 말만 있으면 상태는 계속 대기
quiet_log = run_machine(set(), voiced_frames(y))
check([s for _, s in quiet_log] == ["wait"], "깨움말이 없으면 아무 말에도 깨어나면 안 돼요.")

states.typescript:
// D44 · Part 4 · 비서의 상태 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_states.ts
//   깨움말 → 듣기 → (말이 끝나면) 생각 → 말하기 → 대기 상태 기계: 말하는 중 깨움말이 다시 오면 끊고 듣기로(barge-in), 아무 말이 없으면 포기하고 대기로
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const FRAME = 1280; // 0.08초 조각 = 스트리밍의 한 걸음
const WIN = 5; // 0.4초 = 조각 5개를 이어서 본다
const CENTERS = Array.from({ length: 8 }, (_, i) => i * 500 + 250); // 얼어 있는 앞단: 주파수 띠 8개의 가운데 (250, 750, ... 3750 Hz)
const [A, B, C] = [750, 1750, 2750]; // 낮은 소리 · 높은 소리 · 더 높은 소리
const WAKE = [A, A, B, B, B]; // "하나야" 흉내(합성 신호): 낮은 소리 2조각 → 높은 소리 3조각
const DECOYS = [[B, B, A, A, A], [A, A, A, A, A], [C, C, C, C, C], [A, B, A, B, A], [B, B, B, B, B], [C, C, A, A, A]]; // 비슷하지만 다른 소리

let seed = 2024;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }; // 0~1 (재현 가능한 난수)
const uni = (lo: number, hi: number): number => lo + (hi - lo) * rand();

function frameFeats(y: Float32Array): number[][] {
  // 앞단(학습하지 않음): 0.08초 조각마다 8개 띠의 로그 에너지 → (조각 수, 8)
  const out: number[][] = [];
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    out.push(CENTERS.map((fc) => {
      let re = 0, im = 0;
      for (let n = 0; n < FRAME; n++) { const ph = (2 * Math.PI * fc * n) / SR; re += y[s + n] * Math.cos(ph); im -= y[s + n] * Math.sin(ph); }
      return Math.log((re * re + im * im) / (FRAME * FRAME) + 1e-9);
    }));
  }
  return out;
}

function tones(freqs: number[], jitter = 30, amp = 0.3): Float32Array {
  const y = new Float32Array(freqs.length * FRAME);
  freqs.forEach((f0, k) => {
    const f = f0 + uni(-jitter, jitter), a = amp * uni(0.8, 1.2), ph = uni(0, 6.28);
    for (let n = 0; n < FRAME; n++) y[k * FRAME + n] = a * Math.sin(2 * Math.PI * f * (n / SR) + ph);
  });
  return y;
}
const noise = (n: number, amp = 0.02): Float32Array => Float32Array.from({ length: n }, () => uni(-1, 1) * amp);

function windowSample(freqs: number[], shift = 0): number[] {
  // 소리 5조각(앞뒤 잡음 포함)에서 shift 조각 어긋난 0.4초 창을 잘라 특징 40개로
  const y = noise(9 * FRAME);
  y.set(tones(freqs).map((v, i) => v + y[2 * FRAME + i]), 2 * FRAME);
  return frameFeats(y.slice((2 + shift) * FRAME, (2 + shift + WIN) * FRAME)).flat();
}

function makeData(n: number): [number[][], number[]] {
  // 깨움말 창 (정확히 맞은 것 + 한 조각 어긋난 것)을 정답(1), 비슷한 소리 · 잡음 창을 오답(0)으로
  const X: number[][] = [], y: number[] = [];
  const shifts = [0, -1, 1];
  for (let i = 0; i < n; i++) {
    X.push(windowSample(WAKE, shifts[i % 3])); y.push(1);
    X.push(windowSample(DECOYS[i % DECOYS.length], shifts[Math.floor(i / 2) % 3])); y.push(0);
    X.push(frameFeats(noise(WIN * FRAME)).flat()); y.push(0);
  }
  return [X, y];
}

interface Model { mu: number[]; sd: number[]; w: number[]; b: number }
function train(X: number[][], y: number[], epochs = 400, lr = 0.5): Model {
  // 작은 분류기: 표준화 + 로지스틱 회귀 (장난감 모델, 학습은 순식간)
  const d = X[0].length, n = X.length;
  const mu = Array.from({ length: d }, (_, j) => X.reduce((a, r) => a + r[j], 0) / n);
  const sd = Array.from({ length: d }, (_, j) => Math.sqrt(X.reduce((a, r) => a + (r[j] - mu[j]) ** 2, 0) / n) + 1e-6);
  const Z = X.map((r) => r.map((v, j) => (v - mu[j]) / sd[j]));
  const w = new Array(d).fill(0);
  let b = 0;
  for (let e = 0; e < epochs; e++) {
    const gw = new Array(d).fill(0);
    let gb = 0;
    for (let i = 0; i < n; i++) {
      const g = 1 / (1 + Math.exp(-(Z[i].reduce((a, v, j) => a + v * w[j], 0) + b))) - y[i];
      for (let j = 0; j < d; j++) gw[j] += g * Z[i][j];
      gb += g;
    }
    for (let j = 0; j < d; j++) w[j] -= (lr * gw[j]) / n;
    b -= (lr * gb) / n;
  }
  return { mu, sd, w, b };
}

const score = (m: Model, x: number[]): number => 1 / (1 + Math.exp(-(x.reduce((a, v, j) => a + ((v - m.mu[j]) / m.sd[j]) * m.w[j], 0) + m.b)));

function streamScores(m: Model, y: Float32Array): number[] {
  // 흘러 들어온 소리를 0.08초 조각씩 받아, 조각마다 최근 0.4초 창의 점수 하나 (처음 4조각은 아직 창이 안 차서 0)
  const feats = frameFeats(y);
  const out = new Array(WIN - 1).fill(0);
  for (let i = WIN - 1; i < feats.length; i++) out.push(score(m, feats.slice(i - WIN + 1, i + 1).flat()));
  return out;
}

function detect(scores: number[], thr: number, need = 2, rest = 19): number[] {
  // 점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각(약 1.5초)은 쉬는 시간 → 깨어난 조각 번호들
  const fires: number[] = [];
  let run = 0, cool = 0;
  scores.forEach((s, i) => {
    if (cool > 0) { cool--; return; }
    run = s > thr ? run + 1 : 0;
    if (run >= need) { fires.push(i); run = 0; cool = rest; }
  });
  return fires;
}

function makeStream(wakeAt = [37, 100], decoyAt = [70], n = 150): Float32Array {
  // 12초 소리: 잡음 위에 깨움말 2번(약 3.0초 · 8.0초)과 비슷한 소리 1번(5.6초)
  const y = noise(n * FRAME);
  const put = (at: number, freqs: number[]): void => { const t = tones(freqs); for (let i = 0; i < t.length; i++) y[at * FRAME + i] += t[i]; };
  wakeAt.forEach((at) => put(at, WAKE));
  decoyAt.forEach((at) => put(at, DECOYS[0]));
  return y;
}

function voicedFrames(y: Float32Array, thr = 0.05): boolean[] {
  // 조각마다 소리 크기(RMS)가 문턱을 넘으면 '말하는 중'
  const out: boolean[] = [];
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    let e = 0;
    for (let n = 0; n < FRAME; n++) e += y[s + n] * y[s + n];
    out.push(Math.sqrt(e / FRAME) > thr);
  }
  return out;
}

function runMachine(fires: number[], voiced: boolean[], quietNeed = 5, giveUp = 25, think = 3, speak = 20): [number, string][] {
  // 비서의 상태: 대기 → (깨움말) 듣기 → (말이 끝남) 생각 → 말하기 → 대기. 말하는 중에 깨움말이 다시 오면 끊고 듣기로(barge-in)
  let state = "wait";
  const log: [number, string][] = [[0, "wait"]];
  let heard = 0, quiet = 0, left = 0, t0 = 0;
  voiced.forEach((v, i) => {
    const fired = fires.includes(i), before = state;
    if (state === "wait") {
      if (fired) { state = "listen"; heard = 0; quiet = 0; t0 = i; }
    } else if (state === "listen") {
      if (v) { heard++; quiet = 0; } else if (heard) quiet++;
      if (heard && quiet >= quietNeed) { state = "think"; left = think; }
      else if (!heard && i - t0 > giveUp) state = "wait"; // 아무 말도 없으면 포기하고 대기로
    } else if (state === "think") {
      left--;
      if (left === 0) { state = "speak"; left = speak; }
    } else if (state === "speak") {
      if (fired) { state = "listen"; heard = 0; quiet = 0; t0 = i; }
      else { left--; if (left === 0) state = "wait"; }
    }
    if (state !== before) log.push([i, state]);
  });
  return log;
}

function makeTalk(): Float32Array {
  // 깨움말(10~14조각) → 손님 말(20~34조각) → 비서가 말하는 중 깨움말 다시(52~56조각)
  const y = noise(110 * FRAME);
  const put = (at: number, freqs: number[]): void => { const t = tones(freqs); for (let i = 0; i < t.length; i++) y[at * FRAME + i] += t[i]; };
  put(10, WAKE);
  put(20, [C, C, C, C, C]); put(25, [C, C, C, C, C]); put(30, [C, C, C, C, C]);
  put(52, WAKE);
  return y;
}

const model = train(...makeData(120));
const y = makeTalk();
const fires = detect(streamScores(model, y), 0.9);
const log = runMachine(fires, voicedFrames(y));
console.log("깨움말 감지 조각:", JSON.stringify(fires));
for (const [i, s] of log) console.log(`${((i * FRAME) / SR).toFixed(2)}초 → ${s}`);
check(JSON.stringify(fires) === "[14,56]", "깨움말은 14번째 조각(첫 번째)과 56번째 조각(말하는 중)에서만 감지돼야 해요.");
check(log.map(([, s]) => s).join(",") === "wait,listen,think,speak,listen,wait", "대기 → 듣기 → 생각 → 말하기 → (끼어들기) 듣기 → 말이 없어 대기 순서여야 해요.");

// 깨움말 없이 손님 말만 있으면 상태는 계속 대기
const quietLog = runMachine([], voicedFrames(y));
check(quietLog.length === 1 && quietLog[0][1] === "wait", "깨움말이 없으면 아무 말에도 깨어나면 안 돼요.");

