function choose(offline: boolean, privacyHigh: boolean, needsBigLlm: boolean, latencyMs: number): [string, string] {
  // 클라우드 · 기기 · 섞기 중 고르기: 위에서부터 먼저 맞는 규칙이 이긴다 → [고른 것, 이유]
  if (offline) return ["device", "인터넷이 없어도 돌아야 함"];
