];
for (const [name, args] of cases) { const [got, why] = choose(...args); console.log(`${name} → ${got} (${why})`); }
check(cases.every(([, args, want]) => choose(...args)[0] === want), "오프라인 → 기기, 큰 LLM+개인정보 → 섞기, 큰 LLM → 클라우드, 개인정보 → 기기, 0.3초 미만 → 기기, 나머지 → 클라우드예요.");

