recap.python:
# D44 · Part 5 · 정리 퀴즈 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d44_recap.py   (모의 부품만 써요 · 인터넷·GPU·Docker·마이크 불필요)
#   예산 초과 항목 · 양자화 오차 · 연속 확인 + 쉬는 시간 · 말 끝 판단 · 클라우드/기기 선택 다섯 가지 핵심을 한 번에 자기 확인
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


import struct

import numpy as np


def quantize(w):
    """대칭 int8: 가장 큰 값을 127에 맞춘다 → (정수 배열, 눈금 scale)"""
    scale = float(np.abs(w).max()) / 127
    return np.round(w / scale).astype(np.int8), scale


def dequantize(q, scale):
    return q.astype(np.float32) * np.float32(scale)


def quantize_affine(x):
    """비대칭 uint8(활성값처럼 0 이상일 때): 최소를 0, 최대를 255에 맞추고 영점(zero point)을 기억"""
    lo, hi = float(x.min()), float(x.max())
    scale = (hi - lo) / 255
    zp = int(round(-lo / scale))
    return np.clip(np.round(x / scale) + zp, 0, 255).astype(np.uint8), scale, zp


def pack(q, scale):
    """int8 파일의 속: 앞 4바이트 = float32 눈금, 그 뒤 = 정수 한 바이트씩"""
    return struct.pack("<f", scale) + q.tobytes()


def unpack(buf):
    (scale,) = struct.unpack("<f", buf[:4])
    return np.frombuffer(buf[4:], dtype=np.int8), scale
SR = 16000
FRAME = 1280

import time

BUDGET = dict(size_mb=300, ram_mb=512, load_s=5.0, rtf=0.5)       # 기기(저가 단말, 가상)의 예산. rtf = 처리 시간 ÷ 소리 길이 (1 이하여야 실시간)
PARTS = {                                                         # 부품별 잰 값 (예시 숫자: 진짜 모델을 내려받아 재는 대신 표로 둠)
    "깨움말": dict(size_mb=0.02, ram_mb=5, load_s=0.1, rtf=0.02),
    "ASR small fp32": dict(size_mb=970, ram_mb=1800, load_s=9.0, rtf=1.4),
    "ASR base int8": dict(size_mb=78, ram_mb=300, load_s=1.5, rtf=0.25),
    "TTS": dict(size_mb=60, ram_mb=200, load_s=1.0, rtf=0.15),
}


def over_budget(measured, budget):
    """예산을 넘은 항목 이름들 (같은 키끼리 비교)"""
    return sorted(k for k, v in measured.items() if v > budget[k])


def total(names):
    """고른 부품을 한 기기에 함께 올릴 때: 크기 · 메모리 · 올리는 시간 · rtf 는 모두 더함(차례로 돌리므로)"""
    return {k: sum(PARTS[n][k] for n in names) for k in BUDGET}


def measure_toy():
    """진짜로 재 보기: 12초 합성 소리에서 조각마다 띠 에너지를 뽑는 데 걸린 시간 ÷ 12초 (rtf)"""
    y = np.random.default_rng(0).uniform(-1, 1, 12 * SR).astype(np.float32) * 0.1
    t0 = time.perf_counter()
    f = y[: len(y) // FRAME * FRAME].reshape(-1, FRAME)
    np.log(np.abs(np.fft.rfft(f, axis=1)) ** 2 + 1e-9)
    return (time.perf_counter() - t0) / 12

def choose(offline, privacy_high, needs_big_llm, latency_ms):
    """클라우드 · 기기 · 섞기 중 고르기: 위에서부터 먼저 맞는 규칙이 이긴다 → (고른 것, 이유)"""
    if offline:
        return "device", "인터넷이 없어도 돌아야 함"
    if needs_big_llm and privacy_high:
        return "hybrid", "깨움말 · 받아쓰기는 기기, 생각은 클라우드(개인정보는 가려서)"
    if needs_big_llm:
        return "cloud", "큰 LLM이 필요함"
    if privacy_high:
        return "device", "소리가 기기 밖으로 나가면 안 됨"
    if latency_ms < 300:
        return "device", "네트워크 왕복 시간을 쓸 수 없음"
    return "cloud", "특별한 제약이 없으면 관리가 쉬운 클라우드"


def break_even_calls(device_won, cloud_won_per_call):
    """기기를 한 대 사는 돈(원)이 클라우드 통화 요금(원)과 같아지는 통화 수 (올림, 정수)"""
    return -(-device_won // cloud_won_per_call)



def build(pause_frames):
    """합성 소리: 잡음 → 말 10조각 → 말 속 쉼 pause_frames조각 → 말 8조각 → 긴 잡음 (말 = 1200 Hz 소리)"""
    rng = np.random.default_rng(0)
    noise = lambda n: (rng.uniform(-1, 1, n * FRAME) * 0.02).astype(np.float32)
    speech = lambda n: (0.3 * np.sin(2 * np.pi * 1200 * np.arange(n * FRAME) / SR)).astype(np.float32)
    return np.concatenate([noise(8), speech(10), noise(pause_frames), speech(8), noise(12)])


class Framer:
    """스트리밍 받이: 아무 크기로 들어오는 소리를 쌓았다가 0.08초 조각이 찰 때마다 RMS를 내보낸다"""
    def __init__(self):
        self.buf = np.zeros(0, dtype=np.float32)

    def push(self, x):
        self.buf = np.concatenate([self.buf, x])
        k = len(self.buf) // FRAME
        out = [float(np.sqrt((self.buf[i * FRAME:(i + 1) * FRAME] ** 2).mean())) for i in range(k)]
        self.buf = self.buf[k * FRAME:]
        return out


def endpoints(voiced, need):
    """말 끝 판단: 조용한 조각이 need개 이어지면 말이 끝났다고 보고 → [(시작 조각, 끝났다고 알아챈 조각)]"""
    out, start, quiet = [], None, 0
    for i, v in enumerate(voiced):
        if v:
            start = i if start is None else start
            quiet = 0
        elif start is not None:
            quiet += 1
            if quiet >= need:
                out.append((start, i))
                start, quiet = None, 0
    return out


def detect(scores, thr, need=2, rest=19):
    """점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각은 쉬는 시간 → 깨어난 조각 번호들"""
    fires, run, cool = [], 0, 0
    for i, s in enumerate(scores):
        if cool > 0:
            cool -= 1
            continue
        run = run + 1 if s > thr else 0
        if run >= need:
            fires.append(i)
            run, cool = 0, rest
    return fires

check(over_budget(dict(size_mb=970, ram_mb=1800, load_s=9.0, rtf=1.4), BUDGET) == ["load_s", "ram_mb", "rtf", "size_mb"], "예산보다 큰 항목 이름을 모두 찾아요.")
w = np.array([0.5, -1.0, 0.25], dtype=np.float32)
q, s = quantize(w)
check(list(q) == [64, -127, 32] and float(np.abs(dequantize(q, s) - w).max()) <= s / 2 + 1e-7, "가장 큰 값(-1.0)이 -127이 되고, 오차는 눈금의 절반 이하예요.")
check(detect([0, 0.95, 0.2, 0.95, 0.97, 0.96, 0.95, 0.95], 0.9) == [4], "연속 2조각 넘어야 깨어나고(1번은 무시), 깨어난 뒤에는 쉬는 시간이라 또 깨지 않아요.")
check(endpoints([True, True, False, False, True, False, False, False], 2) == [(0, 3), (4, 6)], "조용한 조각 2개가 이어지면 말이 끝난 거예요.")
check(choose(False, True, True, 500)[0] == "hybrid" and choose(True, True, True, 500)[0] == "device", "오프라인이면 무엇보다 기기, 개인정보 + 큰 LLM이면 섞기예요.")

recap.typescript:
// D44 · Part 5 · 정리 퀴즈 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d44_recap.ts
//   예산 초과 항목 · 양자화 오차 · 연속 확인 + 쉬는 시간 · 말 끝 판단 · 클라우드/기기 선택 다섯 가지 핵심을 한 번에 자기 확인
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function quantize(w: Float32Array): [Int8Array, number] {
  // 대칭 int8: 가장 큰 값을 127에 맞춘다 → [정수 배열, 눈금 scale]
  const scale = w.reduce((m, v) => Math.max(m, Math.abs(v)), 0) / 127;
  return [Int8Array.from(w, (v) => Math.round(v / scale)), scale];
}
const dequantize = (q: Int8Array, scale: number): Float32Array => Float32Array.from(q, (v) => v * Math.fround(scale));

function quantizeAffine(x: Float32Array): [Uint8Array, number, number] {
  // 비대칭 uint8(활성값처럼 0 이상일 때): 최소를 0, 최대를 255에 맞추고 영점(zero point)을 기억
  const lo = x.reduce((m, v) => Math.min(m, v), Infinity), hi = x.reduce((m, v) => Math.max(m, v), -Infinity);
  const scale = (hi - lo) / 255;
  const zp = Math.round(-lo / scale);
  return [Uint8Array.from(x, (v) => Math.min(255, Math.max(0, Math.round(v / scale) + zp))), scale, zp];
}

function pack(q: Int8Array, scale: number): Uint8Array {
  // int8 파일의 속: 앞 4바이트 = float32 눈금, 그 뒤 = 정수 한 바이트씩
  const buf = new Uint8Array(4 + q.length);
  new DataView(buf.buffer).setFloat32(0, scale, true);
  buf.set(new Uint8Array(q.buffer, q.byteOffset, q.length), 4);
  return buf;
}
function unpack(buf: Uint8Array): [Int8Array, number] {
  const scale = new DataView(buf.buffer, buf.byteOffset).getFloat32(0, true);
  return [new Int8Array(buf.slice(4).buffer), scale];
}

const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const FRAME = 1280; // 0.08초 조각

function build(pauseFrames: number): Float32Array {
  // 합성 소리: 잡음 → 말 10조각 → 말 속 쉼 pauseFrames조각 → 말 8조각 → 긴 잡음 (말 = 1200 Hz 소리)
  let seed = 1;
  const noise = (n: number): Float32Array => Float32Array.from({ length: n * FRAME }, () => { seed = (seed * 1103515245 + 12345) % 2147483648; return ((seed / 2147483648) * 2 - 1) * 0.02; });
  const speech = (n: number): Float32Array => Float32Array.from({ length: n * FRAME }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 1200 * i) / SR));
  const parts = [noise(8), speech(10), noise(pauseFrames), speech(8), noise(12)];
  const y = new Float32Array(parts.reduce((a, p) => a + p.length, 0));
  let at = 0;
  for (const p of parts) { y.set(p, at); at += p.length; }
  return y;
}

class Framer {
  // 스트리밍 받이: 아무 크기로 들어오는 소리를 쌓았다가 0.08초 조각이 찰 때마다 RMS를 내보낸다
  buf = new Float32Array(0);
  push(x: Float32Array): number[] {
    const b = new Float32Array(this.buf.length + x.length);
    b.set(this.buf); b.set(x, this.buf.length);
    const k = Math.floor(b.length / FRAME);
    const out: number[] = [];
    for (let i = 0; i < k; i++) {
      let e = 0;
      for (let n = 0; n < FRAME; n++) e += b[i * FRAME + n] ** 2;
      out.push(Math.sqrt(e / FRAME));
    }
    this.buf = b.slice(k * FRAME);
    return out;
  }
}

function endpoints(voiced: boolean[], need: number): [number, number][] {
  // 말 끝 판단: 조용한 조각이 need개 이어지면 말이 끝났다고 보고 → [시작 조각, 끝났다고 알아챈 조각]
  const out: [number, number][] = [];
  let start = -1, quiet = 0;
  voiced.forEach((v, i) => {
    if (v) { if (start < 0) start = i; quiet = 0; }
    else if (start >= 0 && ++quiet >= need) { out.push([start, i]); start = -1; quiet = 0; }
  });
  return out;
}

type Part = { size_mb: number; ram_mb: number; load_s: number; rtf: number };
const BUDGET: Part = { size_mb: 300, ram_mb: 512, load_s: 5.0, rtf: 0.5 }; // 기기(저가 단말, 가상)의 예산. rtf = 처리 시간 ÷ 소리 길이 (1 이하여야 실시간)
const PARTS: Record<string, Part> = { // 부품별 잰 값 (예시 숫자: 진짜 모델을 내려받아 재는 대신 표로 둠)
  "깨움말": { size_mb: 0.02, ram_mb: 5, load_s: 0.1, rtf: 0.02 },
  "ASR small fp32": { size_mb: 970, ram_mb: 1800, load_s: 9.0, rtf: 1.4 },
  "ASR base int8": { size_mb: 78, ram_mb: 300, load_s: 1.5, rtf: 0.25 },
  TTS: { size_mb: 60, ram_mb: 200, load_s: 1.0, rtf: 0.15 },
};
const KEYS = ["size_mb", "ram_mb", "load_s", "rtf"] as const;

// 예산을 넘은 항목 이름들 (같은 키끼리 비교)
const overBudget = (measured: Part, budget: Part): string[] => KEYS.filter((k) => measured[k] > budget[k]).sort();

function total(names: string[]): Part {
  // 고른 부품을 한 기기에 함께 올릴 때: 크기 · 메모리 · 올리는 시간 · rtf 는 모두 더함(차례로 돌리므로)
  const t = { size_mb: 0, ram_mb: 0, load_s: 0, rtf: 0 };
  for (const n of names) for (const k of KEYS) t[k] += PARTS[n][k];
  return t;
}

function measureToy(): number {
  // 진짜로 재 보기: 12초 합성 소리에서 조각마다 띠 에너지를 뽑는 데 걸린 시간 ÷ 12초 (rtf)
  const y = Float32Array.from({ length: 12 * SR }, (_, i) => 0.1 * Math.sin(i * 0.37) * (((i * 7919) % 13) / 13));
  const t0 = performance.now();
  let sink = 0;
  for (let s = 0; s + FRAME <= y.length; s += FRAME) {
    for (let band = 0; band < 8; band++) {
      let re = 0, im = 0;
      const w = (2 * Math.PI * (band * 500 + 250)) / SR;
      for (let n = 0; n < FRAME; n++) { re += y[s + n] * Math.cos(w * n); im -= y[s + n] * Math.sin(w * n); }
      sink += Math.log(re * re + im * im + 1e-9);
    }
  }
  return (performance.now() - t0) / 1000 / 12 + (sink === Infinity ? 1 : 0);
}

function choose(offline: boolean, privacyHigh: boolean, needsBigLlm: boolean, latencyMs: number): [string, string] {
  // 클라우드 · 기기 · 섞기 중 고르기: 위에서부터 먼저 맞는 규칙이 이긴다 → [고른 것, 이유]
  if (offline) return ["device", "인터넷이 없어도 돌아야 함"];
  if (needsBigLlm && privacyHigh) return ["hybrid", "깨움말 · 받아쓰기는 기기, 생각은 클라우드(개인정보는 가려서)"];
  if (needsBigLlm) return ["cloud", "큰 LLM이 필요함"];
  if (privacyHigh) return ["device", "소리가 기기 밖으로 나가면 안 됨"];
  if (latencyMs < 300) return ["device", "네트워크 왕복 시간을 쓸 수 없음"];
  return ["cloud", "특별한 제약이 없으면 관리가 쉬운 클라우드"];
}

// 기기를 한 대 사는 돈(원)이 클라우드 통화 요금(원)과 같아지는 통화 수 (올림, 정수)
const breakEvenCalls = (deviceWon: number, cloudWonPerCall: number): number => Math.ceil(deviceWon / cloudWonPerCall);

function detect(scores: number[], thr: number, need = 2, rest = 19): number[] {
  // 점수가 문턱을 need조각 연속 넘으면 깨어남, 그 뒤 rest조각은 쉬는 시간 → 깨어난 조각 번호들
  const fires: number[] = [];
  let run = 0, cool = 0;
  scores.forEach((s, i) => {
    if (cool > 0) { cool--; return; }
    run = s > thr ? run + 1 : 0;
    if (run >= need) { fires.push(i); run = 0; cool = rest; }
  });
  return fires;
}

